def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]; seen=set(); bad=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
   while stack:
    y,x=stack.pop();cells.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
      seen.add((yy,xx));stack.append((yy,xx))
   if color==5: continue
   a=min(y for y,x in cells);b=max(y for y,x in cells);l=min(x for y,x in cells);u=max(x for y,x in cells)
   expected={(a,x) for x in range(l,u+1)}|{(y,l) for y in range(a,b+1)}
   if set(cells)==expected and b>a and u>l:
    n=max(b-a+1,u-l+1)
    for y in range(a,min(h,a+n)):
     for x in range(l,min(w,l+n)):out[y][x]=color
   else:bad.extend(cells)
 if bad:
  for y in range(min(y for y,x in bad),max(y for y,x in bad)+1):
   for x in range(min(x for y,x in bad),max(x for y,x in bad)+1):out[y][x]=5
 return out

